from pathlib import Path
import json

out = Path(__file__).parent
palette = dict(background='#17191B', surface='#212427', border='#41474C', text='#F1EDE4', muted='#B1B4B5', accent='#A3C4E8', cpu='#B7CCDF', memory='#C5B7DD', storage='#CEBA96', network='#94C9C7', ok='#ABD09B', warn='#F0C477', crit='#F29E98', unavailable='#A3A6AA')
mark = '<path d="M10 4H4V20H10M14 4H20V20H14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="miter"/><path d="M8 12H16" fill="none" stroke="currentColor" stroke-width="2.5"/>'
word = '<g fill="none" stroke="currentColor" stroke-width="3.6" stroke-linecap="round" stroke-linejoin="round"><path d="M18 18C18 8 2 8 2 20S18 32 18 20M18 12V30M29 30V12M29 20C29 9 45 9 45 20V30M72 13C61 6 52 16 62 20L67 22C78 28 64 36 55 28M85 3V30M85 20C85 9 101 9 101 20V30M113 13V30M125 30V12M125 20C125 9 141 9 141 20V30"/></g><circle cx="113" cy="4" r="2.3" fill="currentColor"/>'
def svg(body, view, color='#A3C4E8', title='Anshin Register symbol'):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}" color="{color}" role="img"><title>{title}</title>{body}</svg>'
(out/'symbol.svg').write_text(svg(mark,'0 0 24 24'))
(out/'monochrome.svg').write_text(svg(mark,'0 0 24 24','#000000'))
(out/'wordmark.svg').write_text(svg(word,'0 0 145 36','#F1EDE4','anshin lowercase vector wordmark'))
adaptive = '<rect width="108" height="108" fill="#17191B"/><g transform="translate(30 30) scale(2)" color="#A3C4E8">'+mark+'</g><circle cx="54" cy="54" r="33" fill="none" stroke="#B1B4B5" stroke-width=".5" stroke-dasharray="2 2"/>'
(out/'adaptive-icon.svg').write_text(svg(adaptive,'0 0 108 108',title='Adaptive icon study: foreground within the 66 unit safe circle; dashed guide is not artwork'))
concept = dict(id='02-astra', title='Register', tagline='A clear view of your Machines.', summary='An instrument-like identity built from two open brackets and a shared registration line. Warm charcoal, pale blue interaction cues, and closely aligned numbers make two Machines easy to compare. Connectivity and Verdict remain separate. The identity lives in geometry and typography, so Kanagawa, Tokyo Night, Catppuccin Mocha, and Matte Black can each map their own semantic dark tokens without changing the mark or hierarchy.', personality=['measured','plainspoken','attentive','compact'], logoRationale='Two facing brackets hold a shared reference line. They suggest two Machines within one view and the bounded Window, without suggesting remote control or a guaranteed good Verdict. Three strokes survive at 24px and in one ink. The open space is deliberate: an observation can be incomplete.', typography=dict(ui='Android system sans-serif, Roboto in Compose; system-ui in this artifact', numbers='JetBrains Mono in the native app per design.md; ui-monospace fallback in this dependency-free artifact, tabular numerals', wordmark='Original lowercase monoline vector lettering; no font dependency'), palette=[dict(role=k,hex=v) for k,v in palette.items()], strengths=['Two Machines fit together without a carousel.','Connection freshness precedes any health judgement.','Distinct, reproducible three-stroke symbol; no gradients or borrowed motifs.','Geometry survives all four selectable dark themes.'], tradeoffs=['The abstract mark needs the wordmark during introduction.','Muted chart colors require direct labels and accessible text summaries.','This custom palette is a concept study; named upstream themes need separately verified token mappings.'], files=dict(symbol='symbol.svg',wordmark='wordmark.svg',board='board.html'), attribution=dict(model='gpt-6-astra',effort='high'))
(out/'concept.json').write_text(json.dumps(concept,indent=2)+'\n')

def logo():
    return f'<svg viewBox="0 0 24 24" aria-label="Anshin" class="symbol">{mark}</svg>'
def chart(color='cpu', gap=False):
    lines = '<path d="M4 64L22 61L40 65L58 55L76 57L94 40L112 44"/><path d="M161 48L179 52L197 40L215 50L233 46L251 69L274 72"/>' if gap else '<path d="M4 64L22 61L40 65L58 55L76 57L94 40L112 44L130 61L148 57L166 48L184 52L202 40L220 50L238 46L256 69L274 72"/>'
    return f'<svg class="chart" viewBox="0 0 280 90" role="img" aria-label="Illustrative CPU Window, 0 to 100 percent'+(', with a blank Gap' if gap else '')+'"><g stroke="var(--border)" stroke-width=".6"><path d="M4 16H276M4 50H276M4 84H276"/></g>'+('<rect x="117" y="14" width="39" height="70" fill="var(--background)"/><text x="136" y="36" text-anchor="middle" fill="var(--muted)" font-size="10">Gap</text>' if gap else '')+f'<g fill="none" stroke="var(--{color})" stroke-width="2">{lines}</g></svg>'
def metric(label,value,role,width):
    return f'<div class="metric"><span>{label}</span><b>{value}</b><div class="track"><i style="width:{width}%;background:var(--{role})"></i></div></div>'
def machine(name,verdict,reason,vals,age):
    return f'<article class="machine"><div class="row"><h3>{name}</h3><span class="live">Live</span></div><div class="verdict {verdict}"><b>{verdict}</b><span>{reason}</span></div><div class="metrics">'+''.join(metric(*v) for v in vals)+f'</div><div class="row foot"><span>Last Pulse {age} ago</span><span class="accent">View Machine →</span></div></article>'
swatches=''.join(f'<div class="swatch"><i style="background:{v}"></i><span>{k}<code>{v}</code></span></div>' for k,v in palette.items())
css='\n'.join(f'--{k}:{v};' for k,v in palette.items())
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Anshin · Register design exploration</title><style>
:root{TOKENS}*{box-sizing:border-box}html,body{margin:0;padding:0;background:transparent}body{font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text);font-size:14px;line-height:1.45}.board{max-width:728px;margin:auto;display:grid;gap:14px}.identity,.palette,.notes,.states{background:var(--background);padding:24px}.identity{display:grid;grid-template-columns:1fr 160px;gap:24px}.eyebrow{color:var(--muted);font-size:11px;letter-spacing:.12em;text-transform:uppercase;margin:0 0 15px}.lockup{display:flex;align-items:center;gap:18px}.symbol{width:48px;height:48px;color:var(--accent);flex:none}.wordmark{width:190px;height:48px;color:var(--text)}h1{font-size:22px;font-weight:500;letter-spacing:-.6px;line-height:1.3;margin:23px 0 8px}p{margin:0;color:var(--muted)}.study{display:grid;grid-template-columns:1fr 1fr;align-content:center;gap:12px;text-align:center}.study svg{width:56px;height:56px}.study small{display:block;color:var(--muted);font-size:10px;margin-top:6px}.study .tiny{width:24px;height:24px;margin:16px}.safe{grid-column:1/-1;display:flex;align-items:center;gap:8px;text-align:left}.safe svg{width:64px;height:64px;flex:none}.palette{padding:18px 24px}.sectionline{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px;gap:10px}h2{font-size:15px;font-weight:600;margin:0}.sectionline small{color:var(--muted);font-size:11px}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.swatch{display:flex;gap:8px;align-items:center;font-size:11px}.swatch i{width:22px;height:28px;border:1px solid #ffffff24;flex:none}.swatch code{display:block;color:var(--muted);font-size:10px}.screens{display:grid;grid-template-columns:1fr 1fr;gap:14px}.screen{background:var(--background);border:1px solid var(--border);border-radius:18px;overflow:hidden;display:flex;flex-direction:column;min-width:0}.statusbar{display:flex;justify-content:space-between;padding:13px 20px 6px;font-size:11px;font-weight:600}.status-icons{letter-spacing:3px}.appbar{display:flex;align-items:center;justify-content:space-between;padding:7px 16px;min-height:58px}.appname{display:flex;align-items:center;gap:10px;font-size:22px;letter-spacing:-.5px}.appname .symbol{width:26px;height:26px}.iconbtn{min-height:48px;min-width:48px;display:flex;align-items:center;justify-content:center;color:var(--accent);font-size:23px;background:none;border:0}.content{padding:0 16px 16px}.disclaimer{font-size:10px;color:var(--muted);border-top:1px solid var(--border);padding:9px 0 13px}.overview{padding-bottom:18px}.overview h2{font-size:24px;font-weight:500;letter-spacing:-.6px;margin:3px 0 4px}.overview p{font-size:12px}.warn{color:var(--warn)}.ok{color:var(--ok)}.accent{color:var(--accent)}.machine{padding:16px 0;border-top:1px solid var(--border)}.row{display:flex;align-items:center;justify-content:space-between;gap:8px}.row h3{margin:0;font-size:18px;font-weight:500}.live{font-size:11px;color:var(--text);display:flex;align-items:center;gap:6px}.live:before{content:"";width:6px;height:6px;border:1px solid var(--text);border-radius:50%}.verdict{display:flex;align-items:baseline;gap:9px;font-size:11px;margin:12px 0 16px}.verdict b{font:500 12px ui-monospace,monospace;border:1px solid currentColor;padding:1px 5px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric span{display:block;font-size:10px;color:var(--muted)}.metric b{font:500 21px ui-monospace,monospace;display:block;margin:5px 0 8px}.track{height:3px;background:var(--border)}.track i{display:block;height:3px}.foot{font-size:10px;color:var(--muted);margin-top:19px}.watchnote{padding:15px 0;border-top:1px solid var(--border);font-size:11px;color:var(--muted)}.add{color:var(--accent);font:500 13px system-ui;background:var(--surface);border:1px solid var(--border);border-radius:6px;width:100%;height:48px;margin-top:10px}.gesture{width:96px;height:4px;border-radius:4px;background:var(--muted);margin:18px auto 10px}.screen-bottom{margin-top:auto}.detailbar{justify-content:flex-start;padding-left:3px;gap:3px}.detailbar h2{font-size:19px;font-weight:500}.detailbar .live{margin-left:auto}.reason{border-left:2px solid var(--warn);padding:5px 0 5px 12px;margin:4px 0 16px}.reason .row{margin-bottom:7px}.reason p{font-size:12px;color:var(--text)}.reason small{font-size:10px;color:var(--muted)}.tabs{display:flex;border-bottom:1px solid var(--border);font-size:11px;justify-content:space-between;margin-bottom:14px}.tabs span{padding:13px 2px}.tabs .selected{color:var(--accent);border-bottom:2px solid var(--accent)}.charttitle{font-size:12px}.number{font-family:ui-monospace,monospace;font-variant-numeric:tabular-nums}.charttitle b{font-size:20px;font-weight:500}.chart{width:100%;height:auto;display:block}.axis{display:flex;justify-content:space-between;font-size:9px;color:var(--muted)}.chart-caption{font-size:10px;color:var(--muted);margin:7px 0 14px}.detailrow{display:flex;justify-content:space-between;padding:10px 0;border-top:1px solid var(--border);font-size:11px;gap:8px}.detailrow strong{font-weight:400}.detailrow small{display:block;color:var(--muted);font-size:10px}.stategrid{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.state{padding:13px 0;border-top:1px solid var(--border)}.state h3{font-size:13px;font-weight:500;margin:0 0 5px}.state p{font-size:11px}.state small{display:block;color:var(--muted);font-size:10px;margin-top:7px}.state .number{color:var(--unavailable)}.notes p{font-size:12px}.themechips{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.themechips span{border:1px solid var(--border);border-radius:4px;padding:6px 9px;font-size:11px}.notes small{font-size:10px;color:var(--muted)}@media(max-width:560px){.screens{grid-template-columns:1fr}.screen{max-width:370px;width:100%;margin:auto}.identity{grid-template-columns:1fr}.study{display:flex;justify-content:space-between}.safe{max-width:170px}.swatches{grid-template-columns:repeat(3,1fr)}.stategrid{grid-template-columns:1fr}.sectionline{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="board">
<section class="identity"><div><p class="eyebrow">02 / Register</p><div class="lockup">LOGO<svg class="wordmark" viewBox="0 0 145 36" aria-label="anshin">WORD</svg></div><h1>A clear view of your Machines.</h1><p>Two brackets. One reference line.<br>A small instrument for looking in.</p></div><div class="study"><div><svg viewBox="0 0 24 24" class="tiny" style="color:var(--accent)">MARK</svg><small>24px</small></div><div><svg viewBox="0 0 24 24" style="color:var(--text)">MARK</svg><small>One ink</small></div><div class="safe"><svg viewBox="0 0 108 108">ADAPTIVE</svg><small>Adaptive icon<br>66 / 108 safe circle<br>Guide only</small></div></div></section>
<section class="palette"><div class="sectionline"><h2>Warm charcoal / pale blue</h2><small>Brand accent stays separate from Verdict colors</small></div><div class="swatches">SWATCHES</div></section>
<div class="screens">
<section class="screen" aria-label="Dashboard design"><div class="statusbar"><span>09:41</span><span class="status-icons">▰ ▰ ▰</span></div><header class="appbar"><div class="appname">LOGO<span>anshin</span></div><span class="iconbtn" aria-label="Settings">⚙</span></header><div class="content"><div class="disclaimer">Dashboard · Fictional Machines · Illustrative values</div><div class="overview"><span class="eyebrow">2 Machines · 2 Live</span><h2 class="warn">warn <span style="color:var(--text)">/ storage</span></h2><p>Worst Verdict · Machine B<br>One Reason to take a closer look.</p></div>MACHINES<div class="watchnote">Your phone receives Pulses while Anshin is visible. Each Agent holds its own Window.</div><button class="add" type="button">＋ Add Machine</button></div><div class="screen-bottom"><div class="gesture"></div></div></section>
<section class="screen" aria-label="Machine detail design"><div class="statusbar"><span>09:41</span><span class="status-icons">▰ ▰ ▰</span></div><header class="appbar detailbar"><span class="iconbtn" aria-label="Back">←</span><h2>Machine B</h2><span class="live" style="margin-right:16px">Live</span></header><div class="content"><div class="disclaimer">Machine detail · Illustrative values · Last Pulse 2s ago</div><div class="reason"><div class="row"><b class="warn number">Verdict / warn</b><small>1 Reason</small></div><p>Root filesystem is nearly full.</p><small>92% used · warn begins at 90%</small></div><nav class="tabs" aria-label="Measurement sections"><span class="selected">Overview</span><span>CPU</span><span>Memory</span><span>Storage</span><span>Network</span></nav><div class="row charttitle"><span>CPU · 30-minute Window</span><b class="number">18%</b></div>CHART<div class="axis number"><span>−30 min</span><span>−15 min</span><span>Now</span></div><p class="chart-caption">Scale 0–100% · Gap shown without interpolation</p><div class="detailrow"><span>Memory<small>Used / total</small></span><strong class="number">10.9 / 32 GiB</strong></div><div class="detailrow"><span>Root filesystem<small>Used / capacity</small></span><strong class="number">460 / 500 GiB</strong></div><div class="detailrow"><span>Network<small>Receive / transmit</small></span><strong class="number">2.1 / 0.3 MB/s</strong></div><div class="detailrow"><span>CPU temperature</span><strong class="number">Unavailable</strong></div><div class="detailrow"><span>Battery</span><strong>No battery</strong></div><p class="chart-caption">Unavailable inputs are excluded from the Verdict.</p></div><div class="screen-bottom"><div class="gesture"></div></div></section>
</div>
<section class="states"><div class="sectionline"><h2>When the view is incomplete</h2><small>Illustrative states and ages</small></div><div class="stategrid"><article class="state"><h3>◷ Stale · Machine A</h3><p>Last Pulse 42s ago. Current Verdict unavailable.</p><small class="number">Last CPU 24% · 42s ago</small></article><article class="state"><h3>∅ Unreachable · Machine B</h3><p>Cannot get a Pulse. Last received 3 min ago.</p><small>Current Verdict unavailable. Cause unknown.</small></article><article class="state"><h3>Unavailable measurement</h3><p>CPU temperature · Unavailable</p><small>No value drawn. A missing sensor is never 0°C.</small></article><article class="state"><h3>Gap in the Window</h3><p>The chart above leaves the missing interval blank.</p><small>Agent restarted? Say “Window restarted” and show only the new Window.</small></article><article class="state"><h3>Forbidden</h3><p>The Agent refused this phone.</p><small>Only the Owner's untagged devices may connect.</small></article><article class="state"><h3>Incompatible</h3><p>This app cannot understand the Agent's Pulse version.</p><small>No current Verdict is shown.</small></article></div></section>
<section class="notes"><h2>One identity, four dark themes</h2><div class="themechips"><span>Kanagawa</span><span>Tokyo Night</span><span>Catppuccin Mocha</span><span>Matte Black</span></div><p>Keep the bracket mark, aligned numbers and quiet rows. Map the semantic tokens for each theme; keep interaction blue separate from ok, warn and crit. This board explores a custom charcoal palette, not a certified upstream theme.</p><p style="margin-top:10px">Native Compose intent: tap a Machine, use Android Back, scroll the detail view. Settings holds theme and Machine editing. No remote controls.</p><small style="display:block;margin-top:14px">Static design artifact · All measurements and chart shapes are illustrative · No performance claims</small></section>
</main></body></html>'''
a=[('CPU','24%','cpu',24),('Memory','58%','memory',58),('Root /','42%','storage',42)]
b=[('CPU','18%','cpu',18),('Memory','34%','memory',34),('Root /','92%','storage',92)]
for k,v in dict(TOKENS=css,LOGO=logo(),WORD=word,MARK=mark,ADAPTIVE=adaptive,SWATCHES=swatches,MACHINES=machine('Machine A','ok','No thresholds crossed',a,'2s')+machine('Machine B','warn','Root filesystem nearly full',b,'2s'),CHART=chart(gap=True)).items():
    html=html.replace(k,v)
(out/'board.html').write_text(html)
